update pages set contenu = '{"sections":[]}'::jsonb where path = '/preuves/timescope/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"chiffres","chiffres":[{"valeur":"Février 2024","libelle":"démarrage du contrat de maintenance, la collaboration court toujours"},{"valeur":"1 contrat","libelle":"un cadre unique pour tout le parc, sur les cahiers des charges établis par Timescope"},{"valeur":"2 points techniques","libelle":"étanchéité et réglages, les deux familles de défaillance traitées sur les casques"},{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"Un suivi de maintenance approfondi","libelle":"sur l''ensemble du parc de casques."},{"valeur":"Un partenaire capable de suivre l''évolution technologique","libelle":"rapide de ce secteur émergent."},{"valeur":"Vous cadrez la prestation par un contrat de maintenance.","libelle":"Les techniciens Migen s''engagent à respecter les cahiers des charges établis."},{"valeur":"Vous traitez l''étanchéité","libelle":", qui est le point faible connu de ce type d''équipement en usage public."},{"valeur":"Vous tenez les réglages","libelle":", pour que la performance du casque reste conforme à ce qui est vendu à l''utilisateur."},{"valeur":"Vous recevez des propositions techniques","libelle":", pas seulement des réparations","detail":"Les solutions visent la fiabilité et les performances des casques."},{"valeur":"Vous avancez avec un partenaire qui suit le marché","libelle":", sur un secteur où les technologies évoluent en continu."},{"valeur":"Un suivi de maintenance approfondi sur tout le parc","libelle":"le besoin exprimé au départ par Timescope est couvert par le contrat, sur l''ensemble des casques déployés à travers la France."},{"valeur":"Les deux familles de défaillance traitées","libelle":"l''étanchéité et les réglages des équipements font l''objet de solutions proposées pour la fiabilité et les performances des casques."},{"valeur":"Un partenaire technique tenu dans la durée","libelle":"les cahiers des charges établis par Timescope sont respectés sur un marché où les technologies se succèdent vite."}],"reponse":[{"texte":"Timescope avait deux besoins."},{"texte":"Le second point est le plus exigeant. Sur un marché où les technologies changent vite, un prestataire figé sur une génération d''équipement devient inutile en quelques mois."},{"texte":"Les casques de réalité virtuelle subissent un usage public intensif. Manipulation répétée, poussière, humidité : les pannes viennent de l''environnement autant que de l''électronique."},{"texte":"Traiter cela au coup par coup revient à réparer la même chose indéfiniment. Un contrat de maintenance oblige à regarder la cause, pas seulement le symptôme."},{"texte":"La collaboration, démarrée en février 2024, est toujours en cours."},{"texte":"> [Mettre mon parc sous contrat de maintenance](/contact/)"},{"texte":"Appelez le **04 78 33 72 05**, du lundi au vendredi de 8h00 à 18h30, le rappel arrive dans l''heure. L''astreinte 24/24 et 7/7 s''ajoute en option si votre exploitation tourne le week-end."},{"texte":"Travailler sur une technologie récente demande des techniciens capables d''apprendre vite. Notre sélection retient 10 % des candidats, après entretien technique et comportemental."},{"texte":"> À lire aussi : [Étude de cas ORTHUS x ECOCEM : construction d''un site R&D](/preuves/orthus-ecocem/)"}]}]'::jsonb) where path = '/preuves/timescope/';
